node - <<'NODE'
require('dotenv').config();
const { Client } = require('pg');
const client = new Client({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DATABASE_URL.includes('localhost') ? false : { rejectUnauthorized: false }
});
client.connect()
  .then(async () => {
    const res = await client.query("SELECT table_name, column_name FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('users','bookings','settings') ORDER BY table_name, ordinal_position");
    console.log(JSON.stringify(res.rows));
    await client.end();
  })
  .catch((err) => {
    console.error(err.stack);
    process.exit(1);
  });
NODE
